<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { cambiarDia, cambiarPeriodo, inicializarPeriodos, listarPeriodos, obtenerPeriodo, type Periodo } from '../services/periodos'
const rows=ref<Periodo[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),initialized=ref(true),loading=ref(false),working=ref(false),error=ref(''),success=ref(''),detail=ref<Periodo|null>(null)
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarPeriodos(criterio.value,next);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;initialized.value=r.inicializado}catch(e){error.value=message(e)}finally{loading.value=false}}
async function initialize(){if(!confirm('Se creará el periodo y día operativo correspondiente a la fecha actual. ¿Continuar?'))return;await act(()=>inicializarPeriodos(),'Periodo inicial creado correctamente.');initialized.value=true}
async function show(item:Periodo){try{detail.value=await obtenerPeriodo(item.id)}catch(e){error.value=message(e)}}
async function togglePeriod(item:Periodo){const action=item.cerrado?'aperturar':'cerrar';const warning=item.cerrado?'Se volverá a habilitar este periodo.':'Se cerrará el día vigente, se iniciará el siguiente periodo y se trasladarán los saldos. Esta operación afecta todo el almacén.';if(!confirm(`${warning} ¿Desea continuar?`))return;await act(()=>cambiarPeriodo(item.id,action),`Periodo ${item.cerrado?'aperturado':'cerrado'} correctamente.`)}
async function toggleDay(id:number,closed:boolean){const action=closed?'aperturar':'cerrar';const warning=closed?'Solo puede existir un día abierto por periodo.':'Se cerrará el día y se abrirá automáticamente el siguiente día operativo.';if(!confirm(`${warning} ¿Continuar?`))return;await act(()=>cambiarDia(id,action),`Día ${closed?'aperturado':'cerrado'} correctamente.`);if(detail.value)detail.value=await obtenerPeriodo(detail.value.id)}
async function act(callback:()=>Promise<void>,text:string){working.value=true;error.value='';try{await callback();success.value=text;await load(page.value)}catch(e){error.value=message(e)}finally{working.value=false}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.';onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Almacén / Periodos</nav><header class="hero"><div class="mark">PE</div><div><small>MIA · CONTROL OPERATIVO</small><h1>Periodos de almacén</h1><p>Gestiona el calendario mensual y los cierres diarios.</p></div><b>{{total}} periodos</b><button v-if="!initialized" @click="initialize">Inicializar periodos</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><input v-model.trim="criterio" placeholder="Buscar por mes o año" @keyup.enter="load(1)"><button @click="load(1)">Buscar</button><button class="soft" @click="criterio='';load(1)">Limpiar</button></section><div v-if="loading" class="empty">Cargando periodos…</div><div v-else-if="!initialized" class="empty"><b>El control de periodos aún no ha sido inicializado.</b><span>Utilice “Inicializar periodos” para crear el mes y día operativo actual.</span></div><div v-else-if="!rows.length" class="empty">No se encontraron periodos.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id" :class="{closed:item.cerrado}"><header><div class="calendar"><b>{{String(item.mes).padStart(2,'0')}}</b><span>{{item.anio}}</span></div><div><small>PERIODO MENSUAL</small><h2>{{item.nombre}}</h2></div><em>{{item.cerrado?'CERRADO':'ABIERTO'}}</em></header><dl><div><dt>Inicio</dt><dd>{{item.fecha_inicio}}</dd></div><div><dt>Fin</dt><dd>{{item.fecha_fin}}</dd></div><div><dt>Días procesados</dt><dd>{{item.dias_count}}</dd></div><div><dt>Movimientos</dt><dd>{{item.movimientos_count}}</dd></div></dl><div v-if="item.dia_abierto" class="today"><span>DÍA OPERATIVO</span><b>{{item.dia_abierto.fecha}}</b><em>ABIERTO</em></div><div v-else class="today muted">Sin día operativo abierto</div><footer><button @click="show(item)">Ver días</button><button class="toggle" :class="{open:item.cerrado}" :disabled="working" @click="togglePeriod(item)">{{item.cerrado?'Aperturar':'Cerrar periodo'}}</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog"><header><div><small>DETALLE DEL PERIODO</small><h2>{{detail.nombre}}</h2><p>{{detail.fecha_inicio}} al {{detail.fecha_fin}}</p></div><button @click="detail=null">×</button></header><div class="scroll"><table><thead><tr><th>Fecha</th><th>Estado</th><th>Movimientos</th><th>Fecha de cierre</th><th>Usuario</th><th>Observación</th><th></th></tr></thead><tbody><tr v-for="day in detail.dias||[]" :key="day.id" :class="{current:!day.cerrado}"><td><b>{{day.fecha}}</b></td><td><span :class="day.cerrado?'closed-badge':'open-badge'">{{day.cerrado?'CERRADO':'ABIERTO'}}</span></td><td>{{day.movimientos_count}}</td><td>{{day.fecha_cierre||'—'}}</td><td>{{day.usuario_cierre||'—'}}</td><td>{{day.observacion||'—'}}</td><td><button :class="{reopen:day.cerrado}" :disabled="working||detail?.cerrado" @click="toggleDay(day.id,day.cerrado)">{{day.cerrado?'Aperturar':'Cerrar día'}}</button></td></tr></tbody></table></div><footer><button @click="detail=null">Cerrar</button></footer></section></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.cards small,.dialog small{color:var(--accent);font-size:.49rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>b{margin-left:auto;font-size:.55rem}.hero button,.filters button,.pages button,.dialog button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.53rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:11px;padding:11px;display:flex;gap:6px;border-radius:9px;background:#fff}.filters input{flex:1}.soft{color:#64727a!important;background:#edf1f3!important}input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d9e0e3;border-radius:6px;font:inherit;font-size:.56rem}.empty{margin-top:11px;padding:45px;display:grid;gap:6px;text-align:center;background:#fff;font-size:.6rem}.cards{margin-top:11px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{padding:13px;border:1px solid #e0e5e7;border-top:4px solid #2d9b68;border-radius:9px;background:#fff}.cards article.closed{opacity:.75;border-top-color:#7e8b91}.cards article>header{display:flex;align-items:center;gap:8px}.calendar{width:38px;padding:5px 0;display:grid;place-items:center;border-radius:7px;color:#fff;background:#2d9b68}.calendar b{font-size:.72rem}.calendar span{font-size:.43rem}.closed .calendar{background:#7e8b91}.cards h2{margin:2px 0;font-size:.7rem}.cards header>em{margin-left:auto;padding:4px 6px;border-radius:9px;color:#287154;background:#e7f7ef;font-size:.44rem;font-style:normal}.closed header>em{color:#68767d;background:#edf0f2}.cards dl{margin:10px 0}.cards dl div{padding:5px 0;display:flex;border-bottom:1px solid #edf0f1;font-size:.51rem}.cards dt{color:#78858b}.cards dd{margin-left:auto}.today{padding:8px;display:flex;align-items:center;gap:6px;border-radius:7px;background:#eaf7f0;font-size:.48rem}.today span{color:#287154}.today b{margin-left:auto}.today em{font-style:normal}.today.muted{display:block;text-align:center;color:#7b888e;background:#f1f3f4}.cards footer{margin-top:10px;display:flex}.cards footer button{border:0;color:var(--accent);background:none;font-size:.49rem}.cards footer .toggle{margin-left:auto;color:#b34047}.cards footer .toggle.open{color:#267655}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(1000px,100%);max-height:90vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0;font-size:1rem}.dialog header p{font-size:.55rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.5rem}th,td{padding:8px;border-bottom:1px solid #e7ebed;text-align:left;white-space:nowrap}th{color:#fff;background:#5b6e8e}.current{background:#eff9f4}.open-badge,.closed-badge{padding:4px 6px;border-radius:8px;color:#287154;background:#e7f7ef;font-size:.43rem}.closed-badge{color:#68767d;background:#edf0f2}td button{background:#b8454c!important}.dialog footer{margin-top:10px;text-align:right}@media(max-width:850px){.hero{flex-wrap:wrap}.hero>b{margin-left:0}.cards{grid-template-columns:1fr}}
</style>
